// Un elemento por invitado activo, con su origen tomado del utm_source con que llegó a Calendly.
const BASE = 'https://wiptool.kommo.com/api/v4';
const ORIGEN = { instagram: 340194, ig: 340194, facebook: 340196, fb: 340196, meta_ads: 340198, explee: 340200, email: 340202, brevo: 340202,
  sendinblue: 340202, sitio_web: 340204, google: 340206, linkedin: 340208 };
const LIBRES = /^(gmail|hotmail|outlook|live|yahoo|icloud|msn|aol|protonmail)\./i;
const citas = $('Citas nuevas (Calendly)').all();
const respuestas = $input.all();
const hora = new Intl.DateTimeFormat('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
const dia = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' });
const digitos = (t) => String(t || '').replace(/\D/g, '').slice(-10);
const buscar = (q) => `${BASE}/contacts?with=leads&query=${encodeURIComponent(q)}`;
const salida = [];
respuestas.forEach((resp, i) => {
  const c = citas[i].json;
  for (const inv of resp.json.collection || []) {
    if (inv.status && inv.status !== 'active') continue;
    const qa = inv.questions_and_answers || [];
    const respuesta = (re) => (qa.find((x) => re.test(x.question || '')) || {}).answer || '';
    const correo = String(inv.email || '').trim().toLowerCase();
    const dom = correo.split('@')[1] || '';
    const telefono = respuesta(/tel[eé]f|whats|celular|m[oó]vil|phone/i) || inv.text_reminder_number || '';
    const t = inv.tracking || {};
    const origen = String(t.utm_source || '').toLowerCase();
    // El agente de WhatsApp manda el enlace con utm_content=kommo-<id de la oportunidad>: se usa esa oportunidad directamente.
    const directo = /^kommo-(\d+)$/.exec(String(t.utm_content || ''));
    const nota = [
      `Reunión agendada en Calendly: ${c.nombre_evento}`,
      `Fecha de la reunión: ${c.inicio ? hora.format(new Date(c.inicio)) : '—'}`,
      c.enlace ? `Enlace: ${c.enlace}` : '',
      `Origen: ${origen || 'sin utm_source'}${t.utm_campaign ? ' · campaña ' + t.utm_campaign : ''}${t.utm_content ? ' · ' + t.utm_content : ''}`,
      ...qa.filter((x) => x.answer).map((x) => `${x.question}: ${x.answer}`),
    ].filter(Boolean).join('\n');
    salida.push({ json: {
      clave: inv.uri, evento: c.evento, kommo_lead: directo ? Number(directo[1]) : null, nombre: inv.name || '', correo, telefono,
      empresa: respuesta(/empresa|compa[ñn][ií]a|company|organizaci/i), dominio: LIBRES.test(dom) ? '' : dom, cargo: respuesta(/cargo|puesto|rol\b|job|title/i),
      origen: ORIGEN[origen] || ORIGEN.sitio_web, campana: t.utm_campaign || 'Reunión en Calendly', objetivo: 'reunion',
      fecha: inv.created_at ? dia.format(new Date(inv.created_at)) : '', etiqueta: 'Calendly', nota,
      url_correo: buscar(correo || digitos(telefono)), url_telefono: buscar(digitos(telefono) || correo),
    } });
  }
});
return salida;

const BASE = 'https://wiptool.kommo.com/api/v4';
const EMBUDO = 14551307, CAMPO_ORIGEN = 421634, CAMPO_CAMPANA = 421636;
const ETAPA = { nuevo: 112413251, reunion: 112413255 };
const TEMPRANAS = new Set([112413247, 112413251]); // Leads entrantes y Nuevo
const CERRADAS = new Set([142, 143]);
const normal = $('Lead de la cita (Calendly)').all();
const porCorreo = $('Buscar correo en Kommo (Calendly)').all();
const porTelefono = $('Buscar teléfono en Kommo (Calendly)').all();
// Etapa de cada oportunidad según la última carga del tablero (las creadas en la última hora aún no están: cuentan como tempranas).
const etapaDe = new Map($input.all().map((i) => [Number(i.json.lead_id), Number(i.json.etapa_id)]).filter(([id]) => id));
const cuerpo = (r) => {
  const j = (r && r.json) || {};
  if (typeof j.data !== 'string') return j;
  try { return JSON.parse(j.data); } catch (e) { return {}; }
};
const contactos = (r) => (cuerpo(r)._embedded || {}).contacts || [];
const campo = (code, value, enumCode) => ({ field_code: code, values: [enumCode ? { value, enum_code: enumCode } : { value }] });

return normal.map((n, i) => {
  const f = n.json;
  const base = { clave: f.clave, datos: f };
  const contacto = [...contactos(porCorreo[i]), ...contactos(porTelefono[i])][0];
  // Oportunidad ya identificada (p. ej. la cita viene del enlace del agente de WhatsApp): se actualiza esa, si sigue abierta.
  if (f.kommo_lead && !CERRADAS.has(etapaDe.get(f.kommo_lead))) {
    const id = f.kommo_lead, etapa = etapaDe.get(id);
    const mover = f.objetivo === 'reunion' && (etapa === undefined || TEMPRANAS.has(etapa));
    return { json: { ...base, accion: mover ? 'movida' : 'existente', contacto_id: contacto ? contacto.id : null, kommo_lead_id: id, metodo: 'PATCH', url: `${BASE}/leads`,
      cuerpo: [{ id, tags_to_add: [{ name: f.etiqueta }], ...(mover ? { pipeline_id: EMBUDO, status_id: ETAPA.reunion } : {}) }] } };
  }
  if (contacto) {
    const abiertas = ((contacto._embedded && contacto._embedded.leads) || []).map((l) => l.id)
      .filter((id) => !CERRADAS.has(etapaDe.get(id))).sort((a, b) => b - a);
    if (abiertas[0]) {
      const id = abiertas[0], etapa = etapaDe.get(id);
      const mover = f.objetivo === 'reunion' && (etapa === undefined || TEMPRANAS.has(etapa));
      return { json: { ...base, accion: mover ? 'movida' : 'existente', contacto_id: contacto.id, kommo_lead_id: id, metodo: 'PATCH', url: `${BASE}/leads`,
        cuerpo: [{ id, tags_to_add: [{ name: f.etiqueta }], ...(mover ? { pipeline_id: EMBUDO, status_id: ETAPA.reunion } : {}) }] } };
    }
  }
  const lead = {
    name: f.empresa || f.nombre || f.correo, pipeline_id: EMBUDO, status_id: ETAPA[f.objetivo] || ETAPA.nuevo,
    custom_fields_values: [
      { field_id: CAMPO_ORIGEN, values: [{ enum_id: f.origen }] },
      ...(f.campana ? [{ field_id: CAMPO_CAMPANA, values: [{ value: f.campana }] }] : []),
    ],
    _embedded: { tags: [{ name: f.etiqueta }] },
  };
  if (f.fecha) lead.created_at = Math.floor(new Date(f.fecha + 'T12:00:00-05:00').getTime() / 1000);
  if (contacto) {
    lead._embedded.contacts = [{ id: contacto.id }];
  } else {
    lead._embedded.contacts = [{ name: f.nombre || f.correo, custom_fields_values: [
      ...(f.correo ? [campo('EMAIL', f.correo, 'WORK')] : []),
      ...(f.telefono ? [campo('PHONE', f.telefono, 'WORK')] : []),
